solution.solution.cpp:
#include <algorithm>
#include <functional>
#include <utility>
#include <vector>

template <class K, class V, class Hash = std::hash<K>>
class ChainedMap
{
public:
    ChainedMap() : buckets_(8) {}

    bool put(const K& key, const V& value)
    {
        if (V* existing = find(key))
        {
            *existing = value;
            return false;
        }
        insertNew(key, value);
        return true;
    }

    V* find(const K& key)
    {
        for (auto& entry : bucket(key))
            if (entry.first == key) return &entry.second;
        return nullptr;
    }

    bool contains(const K& key) const
    {
        for (const auto& entry : buckets_[index(key)])
            if (entry.first == key) return true;
        return false;
    }

    bool erase(const K& key)
    {
        auto& chain = bucket(key);
        for (std::size_t i = 0; i < chain.size(); ++i)
            if (chain[i].first == key)
            {
                if (i + 1 != chain.size()) chain[i] = std::move(chain.back());
                chain.pop_back();
                --size_;
                return true;
            }
        return false;
    }

    V& operator[](const K& key)
    {
        if (V* existing = find(key)) return *existing;
        return insertNew(key, V{});
    }

    std::size_t size() const { return size_; }
    std::size_t bucketCount() const { return buckets_.size(); }
    double loadFactor() const { return static_cast<double>(size_) / static_cast<double>(buckets_.size()); }

    std::size_t longestChain() const
    {
        std::size_t longest = 0;
        for (const auto& chain : buckets_) longest = std::max(longest, chain.size());
        return longest;
    }

    template <class F>
    void forEach(F f) const
    {
        for (const auto& chain : buckets_)
            for (const auto& [k, v] : chain) f(k, v);
    }

private:
    using Chain = std::vector<std::pair<K, V>>;

    std::size_t index(const K& key) const { return Hash{}(key) % buckets_.size(); }
    Chain& bucket(const K& key) { return buckets_[index(key)]; }

    V& insertNew(const K& key, V value)
    {
        ++size_;
        if (size_ > buckets_.size()) rehash(buckets_.size() * 2);
        auto& chain = bucket(key);
        chain.emplace_back(key, std::move(value));
        return chain.back().second;
    }

    void rehash(std::size_t count)
    {
        std::vector<Chain> old = std::move(buckets_);
        buckets_ = std::vector<Chain>(count);
        for (auto& chain : old)
            for (auto& entry : chain) bucket(entry.first).push_back(std::move(entry));
    }

    std::vector<Chain> buckets_;
    std::size_t size_ = 0;
};

unitTests:
#include <map>
#include <string>

struct Terrible { std::size_t operator()(int) const { return 0; } };

TEST("put, find and update") {
    ChainedMap<std::string, int> m;
    CHECK(m.put("ada", 36));
    CHECK(m.put("grace", 85));
    CHECK(!m.put("ada", 37));
    CHECK_EQ(m.size(), std::size_t{ 2 });
    CHECK(m.find("ada") != nullptr);
    CHECK_EQ(*m.find("ada"), 37);
    CHECK(m.find("linus") == nullptr);
    CHECK(m.contains("grace"));
    CHECK(!m.contains("linus"));
}
TEST("erase") {
    ChainedMap<int, int> m;
    for (int i = 0; i < 20; ++i) m.put(i, i * i);
    CHECK(m.erase(7));
    CHECK(!m.erase(7));
    CHECK(!m.contains(7));
    CHECK_EQ(m.size(), std::size_t{ 19 });
    CHECK_EQ(*m.find(19), 361);
}
TEST("operator[] counts") {
    ChainedMap<std::string, int> counts;
    for (std::string w : { "a", "b", "a", "c", "a", "b" }) ++counts[w];
    CHECK_EQ(counts["a"], 3);
    CHECK_EQ(counts["b"], 2);
    CHECK_EQ(counts.size(), std::size_t{ 3 });
    CHECK_EQ(counts["zzz"], 0);
    CHECK_EQ(counts.size(), std::size_t{ 4 });
}
TEST("rehashing keeps the load factor at most 1") {
    ChainedMap<int, int> m;
    CHECK_EQ(m.bucketCount(), std::size_t{ 8 });
    for (int i = 0; i < 8; ++i) m.put(i, i);
    CHECK_EQ(m.bucketCount(), std::size_t{ 8 });
    m.put(8, 8);
    CHECK_EQ(m.bucketCount(), std::size_t{ 16 });
    for (int i = 9; i < 1000; ++i) m.put(i * 7919, i);
    CHECK_EQ(m.bucketCount(), std::size_t{ 1024 });
    CHECK(m.loadFactor() <= 1.0);
    CHECK(m.longestChain() <= 8);
    bool all = true;
    for (int i = 9; i < 1000; ++i) all = all && m.find(i * 7919) && *m.find(i * 7919) == i;
    CHECK(all);
}
TEST("correct even when everything collides") {
    ChainedMap<int, std::string, Terrible> m;
    for (int i = 0; i < 50; ++i) m.put(i, std::to_string(i));
    CHECK_EQ(m.longestChain(), std::size_t{ 50 });
    CHECK_EQ(*m.find(42), std::string("42"));
    CHECK(m.erase(0));
    CHECK(m.erase(49));
    CHECK(!m.contains(0));
    CHECK_EQ(m.size(), std::size_t{ 48 });
    CHECK_EQ(*m.find(25), std::string("25"));
}
TEST("visiting every entry") {
    ChainedMap<std::string, int> m;
    std::map<std::string, int> expected;
    for (int i = 0; i < 100; ++i) { m.put("k" + std::to_string(i), i); expected["k" + std::to_string(i)] = i; }
    std::map<std::string, int> seen;
    m.forEach([&](const std::string& k, int v) { seen[k] = v; });
    CHECK(seen == expected);
}
TEST("100,000 entries stay fast") {
    ChainedMap<int, int> m;
    for (int i = 0; i < 100000; ++i) m.put(i, i);
    long long sum = 0;
    for (int i = 0; i < 100000; ++i) sum += *m.find(i);
    CHECK_EQ(sum, 4999950000LL);
    CHECK_EQ(m.bucketCount(), std::size_t{ 131072 });
}

